def is_valid_ipv4(s: str) -> bool:
    if not s:
        return False

    parts = s.split('.')
    if len(parts) != 4:
        return False

    for part in parts:
        if not part:
            return False
        if len(part) > 1 and part[0] == '0':
            return False
        if not part.isdigit() or not (0 <= int(part) <= 255):
            return False

    return True
