def to_snake(name: str) -> str:
    if not name:
        return ""

    result = []
    i = 0

    while i < len(name):
        if name[i].isupper() and i > 0:
            # Check if this uppercase letter is part of a sequence of capitals
            # If it's not the first character and the previous char is lowercase, then it's a word boundary
            if i + 1 < len(name) and name[i+1].isupper() and i + 2 < len(name) and name[i+2].islower():
                # This is a capital in the middle of a word, so we don't split
                result.append(name[i])
                i += 1
                continue
            elif i > 0 and name[i-1].islower():
                # If we're in the middle of a word and see an uppercase letter, it's a new word
                result.append("_" + name[i])
            else:
                result.append(name[i])
        else:
            result.append(name[i])
        i += 1

    # Convert the result to lowercase and join
    return "".join(result).lower()
```

