def lru_simulate(capacity: int, ops: list) -> list:
    from collections import OrderedDict

    cache = OrderedDict()
    results = []

    for op in ops:
        if op[0] == 'put':
            key, value = op[1], op[2]
            if key in cache:
                cache.move_to_end(key)
            else:
                if len(cache) >= capacity:
                    cache.popitem(last=False)
            cache[key] = value
        elif op[0] == 'get':
            key = op[1]
            if key in cache:
                result = cache[key]
                cache.move_to_end(key)
                results.append(result)
            else:
                results.append(-1)

    return results
```

