def word_wrap(text: str, width: int) -> list:
    words = text.split()
    lines = []
    current_line = []
    current_length = 0

    for word in words:
        # Check if adding this word exceeds the width
        # (accounting for space if not the first word in line)
        if current_length > 0:
            if current_length + 1 + len(word) > width:
                # Cannot fit this word, finalize current line
                if current_line:
                    lines.append(" ".join(current_line))
                    current_line = []
                    current_length = 0
                # Start new line with current word
                if len(word) > width:
                    # Word longer than width, place alone on its own line
                    lines.append(word)
                else:
                    current_line = [word]
                    current_length = len(word)
            else:
                # Can fit the word in current line
                current_line.append(word)
                current_length += 1 + len(word)
        else:
            # First word in line
            if len(word) > width:
                # Word longer than width, place alone
                lines.append(word)
            else:
                current_line.append(word)
                current_length = len(word)

    # Add any remaining line
    if current_line:
        lines.append(" ".join(current_line))

    return lines
```

