def deep_merge(a: dict, b: dict) -> dict:
    result = a.copy()
    for key, value_b in b.items():
        if key in result and isinstance(result[key], dict) and isinstance(value_b, dict):
            result[key] = deep_merge(result[key], value_b)
        else:
            result[key] = value_b
    return result
